pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(address caller) internal {
        vm.assume(true);
        bool reverted;
        try c.withdraw(1) { reverted = false; } catch { reverted = true; }
        address owner;
        try c.owner() returns (address __r) { owner = __r; } catch { return; }
        assertTrue(reverted || owner == address(this));
    }

    function testFuzz_run(address caller) public {
        _run(caller);
    }

    receive() external payable { }
}
